// reference headers expose the older ZH string representation.  GameInfo and
// GameSlot retain their canonical declarations; the callsites below select
// the proven retail ILT routes through additive symbols.csv candidates.

#define _BFME_RETAIL_TREE_INSERT_LAYOUT
