// BFME passes these strings by value as a one-pointer StringBase object.  The
// ordinary reference headers expose the older ZH representation, which sends
// the wrong copy/dtor calls in this body.  Keep this ABI slice TU-local.
#define ASCIISTRING_H
#define UNICODESTRING_H
template <typename T> struct StringInlineData
{
	int m_refCount;
	int m_length;
	T m_text[1];
};

template <typename T> class StringBase
{
	friend class AsciiString;
	friend class UnicodeString;

private:
	StringBase() : m_data(0) {}
	StringBase(const T *text);
	StringBase(const StringBase<T> &other);
	~StringBase();

	StringInlineData<T> *m_data;
};

class AsciiString : private StringBase<char>
{
public:
	AsciiString() : StringBase<char>() {}
	AsciiString(const char *text) : StringBase<char>(text) {}
	AsciiString(const AsciiString &other) : StringBase<char>(other) {}
	~AsciiString() {}
	AsciiString &operator=(const AsciiString &other);
	const char *str(void) const { return m_data ? m_data->m_text : ""; }
	int getLength(void) const;
	int compareNoCase(const AsciiString &other) const;
	void toLower(void);
	static AsciiString TheEmptyString;
};

class UnicodeString : private StringBase<unsigned short>
{
public:
	UnicodeString() : StringBase<unsigned short>() {}
	UnicodeString(const unsigned short *text) : StringBase<unsigned short>(text) {}
	UnicodeString(const UnicodeString &other) : StringBase<unsigned short>(other) {}
	~UnicodeString() {}
	UnicodeString &operator=(const UnicodeString &other);
	void translate(const AsciiString &name);
	const unsigned short *str(void) const;
	int getLength(void) const;
	int compareNoCase(const UnicodeString &other) const;
	static UnicodeString TheEmptyString;
};

int operator==(const AsciiString &left, const AsciiString &right);
bool operator<(const AsciiString &left, const AsciiString &right);

